### tache_0a
```javascript
function curry(fn) {
  return function curried(...args) {
    // Assez d'arguments fournis -> on exécute la fonction d'origine
    if (args.length >= fn.length) {
      return fn.apply(this, args);
    }
    // Sinon on renvoie une fonction qui accumule les arguments suivants
    return function (...more) {
      return curried.apply(this, args.concat(more));
    };
  };
}

// Vérifications :
// const add = curry((a, b, c) => a + b + c);
// add(1)(2)(3) === 6
// add(1, 2)(3) === 6
// add(1)(2, 3) === 6
// add(1, 2, 3) === 6
```

### tache_0b
```javascript
function egalProfond(a, b) {
  // Égalité stricte (couvre primitives identiques et même référence)
  if (a === b) return true;

  // Types différents
  if (typeof a !== typeof b) return false;

  // Gestion de null
  if (a === null || b === null) return false;

  // Primitives (dont NaN)
  if (typeof a !== 'object') {
    return Number.isNaN(a) && Number.isNaN(b);
  }

  // Dates
  if (a instanceof Date || b instanceof Date) {
    return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();
  }

  // Expressions régulières
  if (a instanceof RegExp || b instanceof RegExp) {
    return (
      a instanceof RegExp &&
      b instanceof RegExp &&
      a.source === b.source &&
      a.flags === b.flags
    );
  }

  // Tableaux vs objets
  const aEstTableau = Array.isArray(a);
  const bEstTableau = Array.isArray(b);
  if (aEstTableau !== bEstTableau) return false;

  // Comparaison des clés propres
  const clesA = Object.keys(a);
  const clesB = Object.keys(b);
  if (clesA.length !== clesB.length) return false;

  for (const cle of clesA) {
    if (!Object.prototype.hasOwnProperty.call(b, cle)) return false;
    if (!egalProfond(a[cle], b[cle])) return false;
  }

  return true;
}

// Vérifications :
// egalProfond({a:{b:1}}, {a:{b:1}}) === true
// egalProfond([1, [2, 3]], [1, [2, 3]]) === true
// egalProfond({a:1}, {a:2}) === false
```

