function composer(...fns) {
  return function (...args) {
    // Aucune fonction : on renvoie le premier argument tel quel
    if (fns.length === 0) return args[0];

    // Application de droite à gauche
    let resultat = fns[fns.length - 1].apply(this, args);
    for (let i = fns.length - 2; i >= 0; i--) {
      resultat = fns[i].call(this, resultat);
    }
    return resultat;
