```javascript
function creerBST() {
  let racine = null;

  function Noeud(valeur) {
    this.valeur = valeur;
    this.gauche = null;
    this.droite = null;
  }

  return {
    insert(valeur) {
      const nouveau = new Noeud(valeur);

      if (racine === null) {
        racine = nouveau;
        return this;
      }

      let courant = racine;
      while (true) {
        if (valeur < courant.valeur) {
          if (courant.gauche === null) {
            courant.gauche = nouveau;
            break;
          }
          courant = courant.gauche;
        } else if (valeur > courant.valeur) {
          if (courant.droite === null) {
            courant.droite = nouveau;
            break;
          }
          courant = courant.droite;
        } else {
          // Valeur déjà présente : on ignore les doublons
          break;
        }
      }
      return this;
    },

    contains(valeur) {
      let courant = racine;
      while (courant !== null) {
        if (valeur === courant.valeur) return true;
        courant = valeur < courant.valeur ? courant.gauche : courant.droite;
      }
      return false;
    }
  };
}

// Vérifications :
// const bst = creerBST();
// bst.insert(10).insert(5).insert(15);
// bst.contains(5) === true ; bst.contains(99) === false
```

