```javascript
function memoize(fn) {
  const cache = new Map();

  return function (...args) {
    // Clé de cache basée sur les arguments sérialisés
    let cle;
    try {
      cle = JSON.stringify(args);
    } catch (e) {
      // Fallback si les arguments ne sont pas sérialisables
      cle = String(args);
    }

    if (cache.has(cle)) {
      return cache.get(cle);
    }

    const resultat = fn.apply(this, args);
    cache.set(cle, resultat);
    return resultat;
  };
}

// Vérifications :
// const double = memoize(x => x * 2);
// double(5) === 10 ; double(5) === 10 (depuis le cache)
```

