### tache_1a
```javascript
function creerFilePriorite() {
  // Tas binaire min : chaque élément est { val, priorite }
  const tas = [];

  function echange(i, j) {
    const tmp = tas[i];
    tas[i] = tas[j];
    tas[j] = tmp;
  }

  // Fait remonter l'élément à l'index i pour respecter la propriété de tas
  function remonter(i) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (tas[parent].priorite > tas[i].priorite) {
        echange(parent, i);
        i = parent;
      } else {
        break;
      }
    }
  }

  // Fait descendre l'élément à l'index i pour respecter la propriété de tas
  function descendre(i) {
    const n = tas.length;
    while (true) {
      let plusPetit = i;
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      if (gauche < n && tas[gauche].priorite < tas[plusPetit].priorite) {
        plusPetit = gauche;
      }
      if (droite < n && tas[droite].priorite < tas[plusPetit].priorite) {
        plusPetit = droite;
      }
      if (plusPetit === i) break;
      echange(i, plusPetit);
      i = plusPetit;
    }
  }

  return {
    enqueue(val, priorite) {
      tas.push({ val, priorite });
      remonter(tas.length - 1);
    },
    dequeue() {
      if (tas.length === 0) return undefined;
      const min = tas[0];
      const dernier = tas.pop();
      if (tas.length > 0) {
        tas[0] = dernier;
        descendre(0);
      }
      return min.val;
    },
    taille() {
      return tas.length;
    }
  };
}
```

