### tache_1b
```javascript
function creerEventEmitter() {
  const ecouteurs = {};

  return {
    on(event, fn) {
      if (!ecouteurs[event]) ecouteurs[event] = [];
      ecouteurs[event].push(fn);
      return this;
    },
    off(event, fn) {
      if (!ecouteurs[event]) return this;
      ecouteurs[event] = ecouteurs[event].filter((f) => f !== fn);
      if (ecouteurs[event].length === 0) delete ecouteurs[event];
      return this;
    },
    emit(event, ...args) {
      if (!ecouteurs[event] || ecouteurs[event].length === 0) return false;
      // Copie pour éviter les mutations pendant l'itération
      for (const fn of ecouteurs[event].slice()) {
        fn(...args);
      }
      return true;
    }
  };
}
```

