### tache_1d
```javascript
function parcoursEnLargeur(graphe, depart) {
  const visites = [];
  const file = [depart];
  while (file.length > 0) {
    // BFS = FIFO : on retire le premier élément (shift), pas le dernier (pop)
    const noeud = file.shift();
    if (!visites.includes(noeud)) {
      visites.push(noeud);
      for (const voisin of (graphe[noeud] || [])) {
        file.push(voisin);
      }
    }
  }
  return visites;
}
```

