### tache_1e
```javascript
function creerProxy(cible, gestionnaire) {
  const handler = gestionnaire || {};
  const getFn = handler.get || ((c, p) => c[p]);
  const setFn = handler.set || ((c, p, v) => { c[p] = v; return true; });

  const proxy = {};

  // On intercepte chaque propriété existante de la cible via getters/setters
  for (const prop of Object.keys(cible)) {
    Object.defineProperty(proxy, prop, {
      get() {
        return getFn(cible, prop);
      },
      set(valeur) {
        return setFn(cible, prop, valeur);
      },
      enumerable: true,
      configurable: true
    });
  }

  return proxy;
}
```

