function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'closed'; // 'closed' | 'open' | 'half-open'
  let failures = 0;
  let openedAt = 0;
  let halfOpenInProgress = false;

  return async function (...args) {
    if (state === 'open') {
      if (Date.now() - openedAt >= delaiResetMs) {
        state = 'half-open';
        halfOpenInProgress = false;
      } else {
        throw new Error('Circuit breaker is open');
      }
    }

    if (state === 'half-open') {
      if (halfOpenInProgress) {
        throw new Error('Circuit breaker is half-open, trial in progress');
      }
      halfOpenInProgress = true;
    }

    try {
      const result = await fn.apply(this, args);

      if (state === 'half-open') {
        state = 'closed';
        failures = 0;
        halfOpenInProgress = false;
      } else {
        failures = 0;
      }

      return result;
    } catch (err) {
      if (state === 'half-open') {
        state = 'open';
        openedAt = Date.now();
        halfOpenInProgress = false;
      } else {
        failures++;
        if (failures >= seuil) {
          state = 'open';
          openedAt = Date.now();
        }
      }
      throw err;
    }
  };
}

function estPalindrome(s) {
  let i = 0;
  let j = s.length - 1;
  while (i < j) {
    if (s[i] !== s[j]) return false;
    i++;
    j--;
  }
  return true;
}

function pgcd(a, b) {
  while (b !== 0) {
    const temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

function nombreMots(s) {
  const trimmed = s.trim();
  if (trimmed === '') return 0;
  return trimmed.split(/\s+/).length;
}

function fusionTriee(a, b) {
  const result = [];
  let i = 0;
  let j = 0;

  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) {
      result.push(a[i]);
      i++;
    } else {
      result.push(b[j]);
      j++;
    }
  }

  while (i < a.length) {
    result.push(a[i]);
    i++;
  }

  while (j < b.length) {
    result.push(b[j]);
    j++;
  }

  return result;
}

function sontAnagrammes(a, b) {
  if (a.length !== b.length) return false;

  const count = new Map();

  for (const ch of a) {
    count.set(ch, (count.get(ch) || 0) + 1);
  }

  for (const ch of b) {
    if (!count.has(ch)) return false;
    const c = count.get(ch) - 1;
    if (c === 0) {
      count.delete(ch);
    } else {
      count.set(ch, c);
    }
  }

  return count.size === 0;
}

