function remplirMatrice(grille, x, y, nouvelleValeur) {
    if (!Array.isArray(grille) || grille.length === 0) return grille;
    if (y < 0 || y >= grille.length) return grille;
    if (!Array.isArray(grille[y]) || x < 0 || x >= grille[y].length) return grille;

    const cible = grille[y][x];
    if (cible === nouvelleValeur) return grille;

    const pile = [[x, y]];
    while (pile.length > 0) {
        const [cx, cy] = pile.pop();
        if (cy < 0 || cy >= grille.length) continue;
        if (cx < 0 || cx >= grille[cy].length) continue;
        if (grille[cy][cx] !== cible) continue;

        grille[cy][cx] = nouvelleValeur;
        pile.push([cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]);
    }
    return grille;
}
```

