function fusionnerConfig(base, override) {
    const estObjetSimple = (v) =>
        v !== null && typeof v === "object" && !Array.isArray(v);

    const clesInterdites = new Set(["__proto__", "constructor", "prototype"]);

    const copier = (source, cible) => {
        if (!estObjetSimple(source)) return cible;
        for (const cle of Object.keys(source)) {
            if (clesInterdites.has(cle)) continue;
            const valeur = source[cle];
            if (estObjetSimple(valeur)) {
                const sousCible = estObjetSimple(cible[cle]) ? cible[cle] : {};
                cible[cle] = copier(valeur, sousCible);
            } else {
                cible[cle] = valeur;
            }
        }
        return cible;
    };

    const resultat = {};
    copier(base, resultat);
    copier(override, resultat);
    return resultat;
}
