function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'closed'; // 'closed' | 'open' | 'half-open'
  let failures = 0;
  let openedAt = 0;
  let halfOpenInProgress = false;

  return async function (...args) {
    if (state === 'open') {
      if (Date.now() - openedAt >= delaiResetMs) {
        state = 'half-open';
        halfOpenInProgress = false;
      } else {
        throw new Error('Circuit breaker is open');
      }
    }

    if (state === 'half-open') {
      if (halfOpenInProgress) {
        throw new Error('Circuit breaker is half-open, trial in progress');
      }
      halfOpenInProgress = true;
    }

    try {
      const result = await fn.apply(this, args);

      if (state === 'half-open') {
        state = 'closed';
        failures = 0;
        halfOpenInProgress = false;
      } else {
        failures = 0;
      }

