  while (index < s.length) {
    const c = s[index];
    if (/[0-9.]/.test(c)) {
      let numStr = '';
      while (index < s.length && /[0-9.]/.test(s[index])) {
        numStr += s[index++];
      }
      tokens.push(parseFloat(numStr));
    } else if ('+-*/()'.includes(c)) {
      tokens.push(c);
      index++;
    } else {
      throw new Error('Caractère invalide: ' + c);
    }
  }

  let pos = 0;

  function parseExpression() {
    let valeur = parseTerme();
    while (pos < tokens.length && (tokens[pos] === '+' || tokens[pos] === '-')) {
      const op = tokens[pos++];
      const droite = parseTerme();
      if (op === '+') valeur += droite;
      else valeur -= droite;
    }
    return valeur;
  }

  function parseTerme() {
    let valeur = parseFacteur();
    while (pos < tokens.length && (tokens[pos] === '*' || tokens[pos] === '/')) {
      const op = tokens[pos++];
      const droite = parseFacteur();
      if (op === '*') valeur *= droite;
      else valeur /= droite;
    }
    return valeur;
  }

  function parseFacteur() {
    if (pos >= tokens.length) throw new Error('Expression incomplète');
    const token = tokens[pos];
    if (token === '(') {
      pos++;
      const valeur = parseExpression();
      if (tokens[pos] !== ')') throw new Error('Parenthèse fermante manquante');
      pos++;
      return valeur;
    }
    if (token === '-') {
      pos++;
      return -parseFacteur();
    }
    if (token === '+') {
      pos++;
      return parseFacteur();
    }
    if (typeof token === 'number') {
      pos++;
      return token;
    }
    throw new Error('Token inattendu: ' + token);
  }

  const resultat = parseExpression();
  if (pos !== tokens.length) throw new Error('Expression invalide');
