function dijkstra(graphe, depart) {
  const noeuds = new Set();
  for (const noeud in graphe) {
    noeuds.add(noeud);
    for (const voisin in graphe[noeud]) {
      noeuds.add(voisin);
    }
  }
  noeuds.add(depart);

  const distances = {};
  for (const noeud of noeuds) {
    distances[noeud] = Infinity;
  }
  distances[depart] = 0;

  const visites = new Set();

  while (visites.size < noeuds.size) {
    let courant = null;
    let distanceMin = Infinity;
    for (const noeud of noeuds) {
      if (!visites.has(noeud) && distances[noeud] < distanceMin) {
        distanceMin = distances[noeud];
        courant = noeud;
      }
    }

    if (courant === null) break;
    visites.add(courant);

    const voisins = graphe[courant] || {};
    for (const voisin in voisins) {
      const poids = voisins[voisin];
      const nouvelleDistance = distances[courant] + poids;
      if (nouvelleDistance < distances[voisin]) {
        distances[voisin] = nouvelleDistance;
      }
    }
  }

  return distances;
}

